#!/usr/bin/python3
"""Karousel 0.17: primary-screen adaptation, shortcuts and Geometry Change.
Run as the desktop user, WITHOUT sudo. --check performs no changes.
"""
import argparse, base64, datetime, io, json, os, pathlib, shutil, subprocess, sys, tarfile, time
ROOT = pathlib.Path(__file__).resolve().parent
HOME = pathlib.Path.home()
CFG = HOME / '.config'
KWIN = HOME / '.local/share/kwin'
BINDINGS = {
 'karousel-cycle-preset-widths': 'Meta+Return',
 'karousel-column-width-minimize': 'Meta+Ctrl+PgDown',
 'karousel-column-width-maximize': 'Meta+Ctrl+PgUp',
 'karousel-window-toggle-floating': 'Meta+Space',
 'karousel-grid-scroll-focused': 'Meta+Ctrl+Return',
 **{'karousel-focus-'+d.lower(): 'Meta+Ctrl+Alt+'+d for d in ('Left','Right','Up','Down')},
 **{'karousel-window-move-'+d.lower(): 'Meta+Alt+Shift+'+d for d in ('Left','Right','Up','Down')},
}
MOD = {'Meta':0x10000000,'Ctrl':0x04000000,'Alt':0x08000000,'Shift':0x02000000}
KEY = {'Return':0x01000004,'Space':0x20,'PgUp':0x01000016,'PgDown':0x01000017,
       'Left':0x01000012,'Up':0x01000013,'Right':0x01000014,'Down':0x01000015}
def keycode(seq):
    return sum(MOD.get(s,KEY.get(s,0)) for s in seq.split('+'))
def normalize(seq):
    return frozenset(seq.replace('PageUp','PgUp').replace('PageDown','PgDown').split('+'))
def saved_conflicts():
    p=CFG/'kglobalshortcutsrc'
    if not p.exists(): return []
    group=''; problems=[]
    wanted={normalize(v):k for k,v in BINDINGS.items()}
    for line in p.read_text().splitlines():
        if line.startswith('['): group=line
        elif '=' in line:
            action,value=line.split('=',1)
            if group=='[kwin]' and action.startswith('karousel-'): continue
            active=value.split(',',1)[0]
            for seq in active.split(r'\t'):
                if normalize(seq) in wanted: problems.append(f'{seq}: {group} {action}')
    return problems
def writecfg(group,key,value):
    subprocess.run(['kwriteconfig6','--file','kwinrc','--group',group,'--key',key,str(value)],check=True)
def dbus_interfaces():
    import dbus
    bus=dbus.SessionBus()
    # Check connection before any mutation.
    if not bus.name_has_owner('org.kde.KWin') or not bus.name_has_owner('org.kde.kglobalaccel'):
        raise RuntimeError('Запустите из терминала в текущем сеансе KDE, без sudo.')
    def interface(service,path,name): return dbus.Interface(bus.get_object(service,path),name)
    return dbus, interface('org.kde.kglobalaccel','/kglobalaccel','org.kde.KGlobalAccel'), interface('org.kde.KWin','/Scripting','org.kde.kwin.Scripting'), interface('org.kde.KWin','/KWin','org.kde.KWin'), interface('org.kde.KWin','/Effects','org.kde.kwin.Effects')
def live_ids(accel):
    return [list(map(str,a)) for a in accel.allActionsForComponent(['kwin','','','']) if str(a[1]).startswith('karousel-')]
def set_keys(dbus,accel,action,keys):
    a=dbus.Array(action,signature='s'); k=dbus.Array(keys,signature='i')
    accel.setForeignShortcut(a,k)
    actual=[int(x) for x in accel.shortcut(a)]
    if actual!=list(keys): raise RuntimeError('KDE не принял сочетание: '+str(action[1]))
def reload_script(scripting,kwin):
    if scripting.isScriptLoaded('karousel'): scripting.unloadScript('karousel')
    kwin.reconfigure()
    scripting.start()
    time.sleep(1)
def unpack(data,target):
    with tarfile.open(fileobj=io.BytesIO(base64.b64decode(data)),mode='r:gz') as t:
        for m in t:
            p=pathlib.PurePosixPath(m.name)
            if p.is_absolute() or '..' in p.parts or m.issym() or m.islnk():
                raise RuntimeError('Недопустимый путь в архиве')
            if not m.isfile(): continue
            dest=target.joinpath(*p.parts)
            dest.parent.mkdir(parents=True,exist_ok=True)
            dest.write_bytes(t.extractfile(m).read())
def restore_files(backup):
    meta=json.loads((backup/'state.json').read_text())
    for name,target in [('kwinrc',CFG/'kwinrc'),('karousel',KWIN/'scripts/karousel'),('geometry',KWIN/'effects/kwin4_effect_geometry_change')]:
        old=backup/name
        if target.is_dir(): shutil.rmtree(target)
        elif target.exists(): target.unlink()
        if old.is_dir(): shutil.copytree(old,target)
        elif old.is_file(): shutil.copy2(old,target)
    return meta
def rollback(backup,interfaces):
    dbus,accel,scripting,kwin,effects=interfaces
    if scripting.isScriptLoaded('karousel'): scripting.unloadScript('karousel')
    effects.unloadEffect('kwin4_effect_geometry_change')
    meta=restore_files(backup)
    kwin.reconfigure(); scripting.start(); time.sleep(1)
    for item in meta['shortcuts']: set_keys(dbus,accel,item['id'],item['keys'])
    if meta['effect_loaded']: effects.loadEffect('kwin4_effect_geometry_change')
    print('Восстановлено из:',backup)
def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check',action='store_true')
    parser.add_argument('--restore',type=pathlib.Path)
    parser.add_argument('--output',default='eDP-1',help='Имя основного разъёма; по умолчанию eDP-1')
    args=parser.parse_args()
    if args.restore:
        rollback(args.restore.resolve(),dbus_interfaces()); return
    conflicts=saved_conflicts()
    if conflicts: raise RuntimeError('Сочетания заняты; изменения отменены:\n'+'\n'.join(conflicts))
    print('Конфликтов с сохранёнными сочетаниями KDE нет.')
    source=ROOT/'karousel-primary-main.js'
    if not source.exists() or 'function karouselPrimaryOutput()' not in source.read_text():
        raise RuntimeError('Рядом нужен файл karousel-primary-main.js из этого же комплекта.')
    if args.check:
        for action,seq in BINDINGS.items(): print(seq,action)
        print('Проверка завершена. Конфигурация KDE не изменялась.'); return
    interfaces=dbus_interfaces(); dbus,accel,scripting,kwin,effects=interfaces
    for action,seq in BINDINGS.items():
        owner=list(map(str,accel.action(keycode(seq))))
        if owner and not (owner[0]=='kwin' and owner[1].startswith('karousel-')):
            raise RuntimeError(f'Сочетание {seq} занято в работающем KDE: {owner}')
    stamp=datetime.datetime.now().strftime('%Y%m%d-%H%M%S-%f')
    backup=ROOT/'backups'/stamp; backup.mkdir(parents=True)
    for name,target in [('kwinrc',CFG/'kwinrc'),('kglobalshortcutsrc',CFG/'kglobalshortcutsrc'),('karousel',KWIN/'scripts/karousel'),('geometry',KWIN/'effects/kwin4_effect_geometry_change')]:
        if target.is_dir(): shutil.copytree(target,backup/name)
        elif target.exists(): shutil.copy2(target,backup/name)
    old=[{'id':a,'keys':[int(k) for k in accel.shortcut(a)]} for a in live_ids(accel)]
    (backup/'state.json').write_text(json.dumps({'shortcuts':old,'effect_loaded':bool(effects.isEffectLoaded('kwin4_effect_geometry_change'))},ensure_ascii=False,indent=2))
    print('Резервная копия:',backup)
    try:
        if scripting.isScriptLoaded('karousel'): scripting.unloadScript('karousel')
        effects.unloadEffect('kwin4_effect_geometry_change')
        unpack(ARCHIVE_KAROUSEL,KWIN/'scripts')
        unpack(ARCHIVE_EFFECT,KWIN/'effects')
        shutil.copy2(source,KWIN/'scripts/karousel/contents/code/main.js')
        for group,key,value in [
            ('Plugins','karouselEnabled','true'),
            ('Plugins','kwin4_effect_geometry_changeEnabled','true'),
            ('Script-karousel','primaryOutputName',args.output),
            ('Script-karousel','presetWidths','50%, 100%'),
            ('Script-karousel','gapsOuterTop',8),('Script-karousel','gapsOuterBottom',8),
            ('Script-karousel','gapsOuterLeft',8),('Script-karousel','gapsOuterRight',8),
            ('Script-karousel','gapsInnerHorizontal',8),('Script-karousel','untileOnDrag','true'),
            ('Effect-kwin4_effect_geometry_change','Duration',200),
        ]: writecfg(group,key,value)
        kwin.reconfigure(); scripting.start(); time.sleep(1)
        if not scripting.isScriptLoaded('karousel'): raise RuntimeError('KWin не загрузил Karousel')
        ids=live_ids(accel); byname={a[1]:a for a in ids}
        missing=set(BINDINGS)-set(byname)
        if missing: raise RuntimeError('Не зарегистрированы команды: '+str(sorted(missing)))
        for a in ids: set_keys(dbus,accel,a,[])
        for action,seq in BINDINGS.items(): set_keys(dbus,accel,byname[action],[keycode(seq)])
        if not effects.isEffectLoaded('kwin4_effect_geometry_change'):
            effects.loadEffect('kwin4_effect_geometry_change')
        if not effects.isEffectLoaded('kwin4_effect_geometry_change'):
            raise RuntimeError('KWin не загрузил Geometry Change')
        print('Настройки применены. Проверьте памятку и окна на обоих мониторах.')
        print('Откат: /usr/bin/python3 '+str(pathlib.Path(__file__).resolve())+' --restore '+str(backup))
    except Exception:
        print('Не удалось применить настройки; выполняется откат.',file=sys.stderr)
        rollback(backup,interfaces)
        raise

ARCHIVE_KAROUSEL = ''
ARCHIVE_EFFECT = ''
if __name__=='__main__':
    try: main()
    except Exception as exc:
        print('Ошибка:',exc,file=sys.stderr); sys.exit(1)
